            }
            return sessionId.toString();
        } catch (SecurityException e) {
            // Handle cases where a SecurityManager restricts SecureRandom access
            throw new RuntimeException("Failed to generate session ID due to security restrictions.", e);
        } catch (Exception e) {
            // Catch-all safeguard for any unexpected runtime failures during generation
            throw new RuntimeException("Unexpected error during session ID generation.", e);
        }
    }
}
